/* Tensor Reduce Sum */
void fb_tensor_reduce_sum_from_unified(const void *input, void *output,
                                       const size_t *dims, size_t ndims,
                                       const int *reduce_axes, size_t num_axes,
                                       int keep_dims) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->reduce_unified) {
    return; /* Error: no reduce_unified implementation */
  }

  vtable->reduce_unified(FB_REDUCE_SUM,          /* operation */
                         FB_REDUCE_LOCAL, /* scope */
                         input, output, dims, ndims, reduce_axes, num_axes,
                         keep_dims, NULL, 0, /* no workspace needed */
                         NULL                /* default stream */
  );
}

