/* Parallel Reduce Sum */
void fb_prim_reduce_sum_from_unified(const void *input, void *output,
                                     size_t count) {

  const fb_backend_vtable_t *vtable = fb_get_active_vtable();
  if (!vtable || !vtable->reduce_unified) {
    return;
  }

  /* Use 1D tensor reduction */
  size_t dims[1] = {count};
  int reduce_axes[1] = {0};

  vtable->reduce_unified(FB_REDUCE_SUM, FB_REDUCE_LOCAL, input, output,
                         dims, 1, reduce_axes, 1, 0, /* don't keep dims */
                         NULL, 0, NULL);
}

