/* ============================================================================
 * Installer Function
 * ========================================================================= */

/**
 * @brief Install all reduction wrappers from reduce_unified
 *
 * This function checks each vtable entry for reduction operations.
 * If the entry is NULL but reduce_unified exists, it installs the wrapper.
 * This is called by fb_autofill_unified_to_specific() in Strategy 1.
 *
 * @param vtable Vtable to fill with missing reduction wrappers
 */
void fb_autofill_reduction_from_unified(fb_backend_vtable_t *vtable) {
  if (!vtable || !vtable->reduce_unified) {
    return; /* No unified implementation available */
  }

  /* Tensor Reductions */
  if (vtable->tensor_reduce_sum == NULL) {
    vtable->tensor_reduce_sum = fb_tensor_reduce_sum_from_unified;
  }
  if (vtable->tensor_reduce_max == NULL) {
    vtable->tensor_reduce_max = fb_tensor_reduce_max_from_unified;
  }
  if (vtable->tensor_reduce_min == NULL) {
    vtable->tensor_reduce_min = fb_tensor_reduce_min_from_unified;
  }
  if (vtable->tensor_reduce_mean == NULL) {
    vtable->tensor_reduce_mean = fb_tensor_reduce_mean_from_unified;
  }
  if (vtable->tensor_reduce_norm_l1 == NULL) {
    vtable->tensor_reduce_norm_l1 = fb_tensor_reduce_norm_l1_from_unified;
  }
  if (vtable->tensor_reduce_norm_l2 == NULL) {
    vtable->tensor_reduce_norm_l2 = fb_tensor_reduce_norm_l2_from_unified;
  }

  /* Parallel Primitive Reductions */
  if (vtable->prim_reduce_sum == NULL) {
    vtable->prim_reduce_sum = fb_prim_reduce_sum_from_unified;
  }
  if (vtable->prim_reduce_max == NULL) {
    vtable->prim_reduce_max = fb_prim_reduce_max_from_unified;
  }
  if (vtable->prim_reduce_min == NULL) {
    vtable->prim_reduce_min = fb_prim_reduce_min_from_unified;
  }
  if (vtable->prim_reduce_product == NULL) {
    vtable->prim_reduce_product = fb_prim_reduce_product_from_unified;
  }

  /* Scan Operations */
  if (vtable->prim_scan_sum_inclusive == NULL) {
    vtable->prim_scan_sum_inclusive = fb_prim_scan_sum_inclusive_from_unified;
  }
  if (vtable->prim_scan_sum_exclusive == NULL) {
    vtable->prim_scan_sum_exclusive = fb_prim_scan_sum_exclusive_from_unified;
  }
  if (vtable->prim_scan_max_inclusive == NULL) {
    vtable->prim_scan_max_inclusive = fb_prim_scan_max_inclusive_from_unified;
  }
  if (vtable->prim_scan_max_exclusive == NULL) {
    vtable->prim_scan_max_exclusive = fb_prim_scan_max_exclusive_from_unified;
  }
  if (vtable->prim_scan_min_inclusive == NULL) {
    vtable->prim_scan_min_inclusive = fb_prim_scan_min_inclusive_from_unified;
  }
  if (vtable->prim_scan_min_exclusive == NULL) {
    vtable->prim_scan_min_exclusive = fb_prim_scan_min_exclusive_from_unified;
  }
  if (vtable->prim_scan_product_inclusive == NULL) {
    vtable->prim_scan_product_inclusive =
        fb_prim_scan_product_inclusive_from_unified;
  }
  if (vtable->prim_scan_product_exclusive == NULL) {
    vtable->prim_scan_product_exclusive =
        fb_prim_scan_product_exclusive_from_unified;
  }

  /* Statistical Reductions */
  if (vtable->stats_sum == NULL) {
    vtable->stats_sum = fb_stats_sum_from_unified;
  }
  if (vtable->stats_mean == NULL) {
    vtable->stats_mean = fb_stats_mean_from_unified;
  }
  if (vtable->stats_variance == NULL) {
    vtable->stats_variance = fb_stats_variance_from_unified;
  }
  if (vtable->stats_std_dev == NULL) {
    vtable->stats_std_dev = fb_stats_std_dev_from_unified;
  }

  /* Collective Communication Reductions */
  if (vtable->nccl_allreduce == NULL) {
    vtable->nccl_allreduce = fb_nccl_allreduce_from_unified;
  }
  if (vtable->nccl_reduce == NULL) {
    vtable->nccl_reduce = fb_nccl_reduce_from_unified;
  }
  if (vtable->nccl_reduce_scatter == NULL) {
    vtable->nccl_reduce_scatter = fb_nccl_reduce_scatter_from_unified;
  }
}

